        "label": "Optimized · sort + two pointers",
        "complexity": {
          "time": "O(n³)",
          "space": "O(1)"
        },
        "pseudocode": [
          "sort(arr)",
          "for i: skip if arr[i] == arr[i − 1]",
          "    for j > i: skip duplicates;  lo ← j + 1;  hi ← n − 1",
          "        if sum == target: record, skip duplicates, move both",
          "        else if sum < target: lo ← lo + 1",
          "        else: hi ← hi − 1",
          "return quadruples"
        ],
