        "label": "Better · precompute maxL[] and maxR[] arrays",
        "complexity": {
          "time": "O(n)",
          "space": "O(n)"
        },
        "pseudocode": [
          "given h[]",
          "maxL ← array of size n",
          "maxL[0] = h[0]",
          "for i ← 1 to n − 1:",
          "    maxL[i] = max(maxL[i − 1], h[i])",
          "maxR ← array of size n",
          "maxR[n − 1] = h[n − 1]",
          "for i ← n − 2 down to 0:",
          "    maxR[i] = max(maxR[i + 1], h[i])",
          "total ← 0",
          "for i ← 0 to n − 1:",
          "    total += max(0, min(maxL[i], maxR[i]) − h[i])",
          "return total"
        ],
