          "for R from 0 to n - 1:",
          "    windowSum ← windowSum + nums[R]",
          "    if R >= k - 1:",
          "        maxSum ← max(maxSum, windowSum)",
          "        windowSum ← windowSum - nums[R - k + 1]",
          "return maxSum"
