        "complexity": {
          "time": "O(n)",
          "space": "O(n)"
        },
        "pseudocode": [
          "stack ← [], ans ← array of 0s",
          "for i from 0 to n - 1:",
          "    while stack not empty and arr[i] resolves arr[stack.top()]:",
          "        prev ← stack.pop()",
          "        ans[prev] ← i - prev",
          "    stack.push(i)",
          "return ans"
        ],
